const results = $input.all();
const cantidadRegistros = results.length;

let yaProcesado = false;
let statusExistente = null;

if (cantidadRegistros > 0 && results[0].json && results[0].json.quote_id) {
  yaProcesado = true;
  statusExistente = results[0].json.status;
}

const quoteId = $('Generar Hash Idempotencia').item.json.quote_id;
const chatId = $('Generar Hash Idempotencia').item.json.chat_id;
const mensajeCliente = $('Generar Hash Idempotencia').item.json.mensaje_cliente;

return [{
  json: {
    quote_id: quoteId,
    chat_id: chatId,
    mensaje_cliente: mensajeCliente,
    ya_procesado: yaProcesado,
    cantidad_registros: cantidadRegistros,
    status_existente: statusExistente
  }
}];

const corregido = $('Detectar Ajustes').item.json || {};
const productos = Array.isArray(corregido.productos) ? corregido.productos : [];
let productosTexto = 'No disponible';
if (productos.length > 0) {
  productosTexto = productos.map(p => `SKU: ${p.sku} | Cant: ${p.cantidad} | Precio: $${p.precio_unit} | Desc: ${p.descuento_pct}% | Subtotal: $${p.subtotal}`).join('\n');
}
const totalFinal = Number(corregido.total_final) || 0;
const plazoPago = corregido.plazo_pago || 'N/A';
const chatId = $('Generar Hash Idempotencia').item.json.chat_id;
let razonTecnica = 'Sin dictamen';
try { razonTecnica = $('Ejecutar Worker 3: Juez').item.json.razon_tecnica || razonTecnica; } catch (e) {}
return [{
  json: {
    cliente: chatId, sku_productos: productosTexto, total: totalFinal, plazo_pago: plazoPago,
    status: 'Aprobado', dictamen_juez: razonTecnica, razon_tecnica: razonTecnica,
    fecha_creacion: new Date().toISOString()
  }
}];

const entrada = $input.first().json;
const message = entrada.message || $('Telegram Trigger').item.json.message;
const texto = (message.text || '').trim().toLowerCase();
const chatId = message.chat.id;
const esConfirmo = /^(confirmo|confirmar|confirmado)$/.test(texto);
const esCancelar = /^(cancelo|cancelar|cancelado)$/.test(texto);
return [{ json: { es_confirmacion: esConfirmo || esCancelar, accion_cliente: esConfirmo ? 'confirmo' : (esCancelar ? 'cancelar' : 'nuevo'), chat_id: chatId, texto_original: message.text } }];

const filas = $input.all().map(i => i.json).filter(f => f && f.quote_id);
const accion = $('Clasificar Confirmación').item.json.accion_cliente;
const chatId = $('Clasificar Confirmación').item.json.chat_id;
if (filas.length === 0) { return [{ json: { encontrado: false, chat_id: chatId, accion_cliente: accion } }]; }
filas.sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0));
const pedido = filas[0];
let productos = pedido.productos || [];
if (typeof productos === 'string') { try { productos = JSON.parse(productos); } catch (e) { productos = []; } }
if (!Array.isArray(productos)) productos = [];
const productosTexto = productos.length > 0 ? productos.map(p => `SKU: ${p.sku} | Cant: ${p.cantidad} | Precio: $${p.precio_unit} | Desc: ${p.descuento_pct}% | Subtotal: $${p.subtotal}`).join('\n') : 'No disponible';
let total = Number(pedido.total_final) || 0;
if (!total && productos.length) { total = productos.reduce((s, p) => s + (Number(p.subtotal) || 0), 0); }
return [{ json: { encontrado: true, chat_id: chatId, quote_id: pedido.quote_id, accion_cliente: accion, nuevo_status: accion === 'confirmo' ? 'COMPLETED' : 'REJECTED_BY_CLIENT', sku_productos: productosTexto, total: total, plazo_pago: pedido.plazo_pago || 'N/A' } }];

