const entrada = $input.first().json;
const message = entrada.message || $('Telegram Trigger').item.json.message;

if (!message || !message.text) {
  return [];
}

const chatId = message.chat.id;
const mensaje = message.text.toLowerCase().trim();
const messageId = message.message_id;

const rawString = `${chatId}_${mensaje}`;

let hash = 5381;
for (let i = 0; i < rawString.length; i++) {
  hash = (hash * 33) ^ rawString.charCodeAt(i);
}
const quoteId = (hash >>> 0).toString(36);

return [{
  json: {
    quote_id: quoteId,
    chat_id: chatId,
    message_id: messageId,
    mensaje_cliente: message.text
  }
}];

const status = $('Code in JavaScript2').item.json.status_existente;
const chatId = $('Generar Hash Idempotencia').item.json.chat_id;
let mensaje = '';
switch(status) {
  case 'COMPLETED': mensaje = '📋 Solicitud ya aprobada 

Estimado cliente, tu pedido ya fue procesado y aprobado anteriormente.'; break;
  case 'PENDING_HUMAN': mensaje = '⏳ Solicitud en revisión 

Estimado cliente, tu pedido ya fue recibido y está siendo revisado por nuestro equipo de gerencia.'; break;
  case 'APPROVED_BY_HUMAN': mensaje = '✅ Pedido aprobado 

Estimado cliente, tu pedido ya fue aprobado manualmente por gerencia.'; break;
  case 'REJECTED_BY_HUMAN': mensaje = '❌ Pedido no aprobado 

Estimado cliente, tu solicitud anterior no fue aprobada por gerencia.'; break;
  case 'AWAITING_CLIENT_CONFIRM': mensaje = '⏳ Esperando tu confirmación 

Tu pedido fue aprobado por gerencia con condiciones ajustadas y estamos esperando tu respuesta. Respondé CONFIRMO para registrarlo o CANCELAR para descartarlo.'; break;
  case 'REJECTED_BY_CLIENT': mensaje = '❌ Pedido cancelado 

Esta solicitud fue cancelada por vos anteriormente.'; break;
  default: mensaje = '📋 Solicitud en proceso 

Estimado cliente, tu pedido ya fue recibido y está siendo procesado.';
}
return [{ json: { chat_id: chatId, text: mensaje, parse_mode: 'Markdown' } }];

const rag = $input.first().json;
const mensajeCliente = $('Generar Hash Idempotencia').item.json.mensaje_cliente;
return [{ json: { ...rag, mensaje_cliente: mensajeCliente } }];

// =====================================================
// Detectar Ajustes - Manager
// Con guardas de fallo técnico + decisión HITL por TOPES GLOBALES
// =====================================================

// 1. Mensaje original del cliente
const mensajeOriginal = $('Generar Hash Idempotencia').item.json.mensaje_cliente;

// 2. Pedido ajustado del Worker 2
const pedidoAjustado = $('Ejecutar Worker 2: Armador').item.json;
const productosWorker2 = pedidoAjustado.productos || pedidoAjustado.evaluacion?.productos || [];

// 🛡️ GUARDA 1: si el Worker 2 falló (moderación o JSON inválido), no fingir ajustes
const worker2Ok = Array.isArray(productosWorker2) && productosWorker2.length > 0 && !pedidoAjustado.error;

if (!worker2Ok) {
  return [{
    json: {
      ...pedidoAjustado,
      productos: [],
      total_final: 0,
      mensaje_original: mensajeOriginal,
      descuento_solicitado: parseInt(mensajeOriginal.match(/(\d+)%/)?.[1] || 0),
      descuento_ajustado: 0,
      plazo_solicitado: parseInt(mensajeOriginal.match(/(\d+)\s*d[ií]as?/)?.[1] || 0),
      plazo_ajustado: 0,
      cantidad_solicitada: parseInt(mensajeOriginal.match(/(\d+)\s+unidades?/)?.[1] || 0),
      cantidad_ajustada: 0,
      reduccion_descuento_pct: 0,
      reduccion_plazo_pct: 0,
      requiere_aprobacion_humana: true,
      worker2_fallo: true,
      razon_tecnica_ajustes: 'FALLO TÉCNICO: el Worker 2 (Armador) no devolvió un pedido estructurado (el LLM respondió moderación o JSON inválido). El pedido requiere revisión manual completa.'
    }
  }];
}

// 3. 🔧 CATÁLOGO DEL RAG (Worker 1) = fuente de verdad del precio base
const ragOutput = $('Ejecutar Worker 1: RAG').item.json;
const productosRAG = ragOutput.productos || ragOutput.result?.productos || [];

// 4. Valores solicitados por el cliente (regex)
const descuentoSolicitado = parseInt(mensajeOriginal.match(/(\d+)%/)?.[1] || 0);
const plazoSolicitado = parseInt(mensajeOriginal.match(/(\d+)\s*d[ií]as?/)?.[1] || 0);
const cantidadRegex = parseInt(mensajeOriginal.match(/(\d+)\s+unidades?/)?.[1] || 0);

// 5. 🔧 Reconstruir productos con PRECIO BASE real (evita descuento doble)
let productosFinales = [];
let totalFinal = 0;

for (const p of productosWorker2) {
  const registroRAG = productosRAG.find(r => r.sku === p.sku);
  const precioBase = Number(registroRAG?.precio_base) || 0;
  const descuento = Number(p.descuento_pct) || 0;
  const cantidad = (productosWorker2.length === 1 && cantidadRegex)
    ? cantidadRegex
    : (Number(p.cantidad) || 0);
  const subtotal = cantidad * precioBase * (1 - descuento / 100);

  productosFinales.push({
    sku: p.sku,
    cantidad: cantidad,
    precio_unit: precioBase,          // ← precio BASE, sin descuento
    descuento_pct: descuento,
    subtotal: Math.round(subtotal * 100) / 100
  });
  totalFinal += subtotal;
}

totalFinal = Math.round(totalFinal * 100) / 100;

// Fallback si no hubo productos
if (productosFinales.length === 0) {
  productosFinales = productosWorker2;
  totalFinal = Number(pedidoAjustado.total_final) || 0;
}

// 🛡️ GUARDA 2: si el RAG no trajo precios base, el total no es confiable
// Evita aprobación automática con Total $0
const sinPrecio = productosFinales.some(p => !Number(p.precio_unit));
if (productosFinales.length > 0 && sinPrecio) {
  return [{
    json: {
      ...pedidoAjustado,
      productos: [],
      total_final: 0,
      mensaje_original: mensajeOriginal,
      descuento_solicitado: descuentoSolicitado,
      descuento_ajustado: 0,
      plazo_solicitado: plazoSolicitado,
      plazo_ajustado: 0,
      cantidad_solicitada: cantidadRegex,
      cantidad_ajustada: 0,
      reduccion_descuento_pct: 0,
      reduccion_plazo_pct: 0,
      requiere_aprobacion_humana: true,
      worker1_fallo: true,
      razon_tecnica_ajustes: 'FALLO TÉCNICO: el Worker 1 (RAG) no devolvió el catálogo/precios base. No se puede calcular un total confiable. Revisión manual requerida.'
    }
  }];
}

// 6. Valores ajustados para la comparación
const producto = productosFinales[0] || {};
const descuentoAjustado = Number(producto.descuento_pct) || 0;
const plazoAjustadoStr = pedidoAjustado.plazo_pago || pedidoAjustado.evaluacion?.plazo_pago || '0';
const plazoAjustado = parseInt(plazoAjustadoStr) || 0;
const cantidadSolicitada = cantidadRegex || Number(producto.cantidad) || 0;
const cantidadAjustada = cantidadSolicitada;

// 7. Reducciones (solo informativas, ya no deciden HITL)
const reduccionDescuento = descuentoSolicitado > 0
  ? ((descuentoSolicitado - descuentoAjustado) / descuentoSolicitado) * 100
  : 0;
const reduccionPlazo = plazoSolicitado > 0
  ? ((plazoSolicitado - plazoAjustado) / plazoSolicitado) * 100
  : 0;

// 🎯 8. NUEVA DECISIÓN: HITL solo si la SOLICITUD excede los TOPES GLOBALES de política
// (antes usaba % de reducción y castigaba ajustes legítimos de catálogo por volumen)
const DESCUENTO_MAX_GLOBAL = 10;  // % máximo absoluto permitido por política
const PLAZO_MAX_GLOBAL = 30;      // días máximos absolutos permitidos por política
const violaTopeDescuento = descuentoSolicitado > DESCUENTO_MAX_GLOBAL;
const violaTopePlazo = plazoSolicitado > PLAZO_MAX_GLOBAL;
const requiereAprobacionHumana = violaTopeDescuento || violaTopePlazo;

// 9. Razón técnica
let razonTecnica = '';
if (requiereAprobacionHumana) {
  razonTecnica = 'VIOLACIÓN DE POLÍTICA GLOBAL. ';
  if (violaTopeDescuento) razonTecnica += `Descuento solicitado ${descuentoSolicitado}% excede el máximo global de ${DESCUENTO_MAX_GLOBAL}%. `;
  if (violaTopePlazo) razonTecnica += `Plazo solicitado ${plazoSolicitado} días excede el máximo global de ${PLAZO_MAX_GLOBAL} días. `;
  razonTecnica += `El sistema ajustó a ${descuentoAjustado}% / ${plazoAjustado} días. Requiere aprobación de gerencia.`;
} else {
  razonTecnica = `Solicitud dentro de topes globales. Ajuste de catálogo aplicado: descuento ${descuentoSolicitado}% -> ${descuentoAjustado}%, plazo ${plazoSolicitado} -> ${plazoAjustado} días.`;
}

return [{
  json: {
    ...pedidoAjustado,
    productos: productosFinales,
    total_final: totalFinal,
    mensaje_original: mensajeOriginal,
    descuento_solicitado: descuentoSolicitado,
    descuento_ajustado: descuentoAjustado,
    plazo_solicitado: plazoSolicitado,
    plazo_ajustado: plazoAjustado,
    cantidad_solicitada: cantidadSolicitada,
    cantidad_ajustada: cantidadAjustada,
    reduccion_descuento_pct: Math.round(reduccionDescuento),
    reduccion_plazo_pct: Math.round(reduccionPlazo),
    requiere_aprobacion_humana: requiereAprobacionHumana,
    razon_tecnica_ajustes: razonTecnica
  }
}];

const ajustes = $input.first().json;
const rag = $('Ejecutar Worker 1: RAG').item.json;
return [{
  json: {
    pedido_generado: {
      cliente_id: ajustes.cliente_id, productos: ajustes.productos, total_final: ajustes.total_final,
      plazo_pago: ajustes.plazo_pago, justificacion_ajustes: ajustes.justificacion_ajustes,
      fuentes_citadas: ajustes.fuentes_citadas, mensaje_original: ajustes.mensaje_original
    },
    politicas_base: {
      productos: rag.productos, regla_descuento: rag.regla_descuento,
      plazo_pago_max: rag.plazo_pago_max, fuentes_citadas: rag.fuentes_citadas
    }
  }
}];

const quoteId = $('Generar Hash Idempotencia').item.json.quote_id;
const chatIdGerentes = '-1004353798072';
const ajustes = $('Detectar Ajustes').item.json || {};
let razonTecnica = '';
if (ajustes.requiere_aprobacion_humana) {
  razonTecnica = `AJUSTES SIGNIFICATIVOS DETECTADOS.`;
  razonTecnica += `Descuento solicitado: ${ajustes.descuento_solicitado}% -> Ajustado: ${ajustes.descuento_ajustado}% (reducción ${ajustes.reduccion_descuento_pct}%).`;
  razonTecnica += `Plazo solicitado: ${ajustes.plazo_solicitado} días -> Ajustado: ${ajustes.plazo_ajustado} días (reducción ${ajustes.reduccion_plazo_pct}%).`;
  razonTecnica += `Requiere aprobación de gerencia.`;
} else {
  try {
    const juez = $('Ejecutar Worker 3: Juez').item.json;
    razonTecnica = juez.razon_tecnica || 'Riesgo detectado por el sistema de auditoría (Score < 4).';
  } catch (error) {
    razonTecnica = 'Riesgo detectado por el sistema de auditoría. Revisión manual requerida.';
  }
}
const replyMarkup = { inline_keyboard: [[ { text: '✅ Aprobar Excepción', callback_data: 'approve_' + quoteId }, { text: '❌ Rechazar Pedido', callback_data: 'reject_' + quoteId } ]] };
return [{ json: { chat_id: chatIdGerentes, text: '⚠️ ALERTA DE GOBERNANZA ⚠️\n\nEl pedido ha sido bloqueado por el Supervisor.\n Razón: ' + razonTecnica + '\n\nPor favor, tome una acción:', parse_mode: 'Markdown', reply_markup: JSON.stringify(replyMarkup), quote_id: quoteId } }];

